import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type RadioGroupSize = "sm" | "md" | "lg";
export type RadioGroupVariant = "orb" | "command" | "segment" | "tile";
export type RadioGroupOrientation = "vertical" | "horizontal";

export interface RadioGroupProps
  extends Omit<React.HTMLAttributes<HTMLFieldSetElement>, "defaultValue" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (
    value: string,
    event: React.ChangeEvent<HTMLInputElement>,
  ) => void;
  name?: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  radioSize?: RadioGroupSize;
  variant?: RadioGroupVariant;
  orientation?: RadioGroupOrientation;
  disabled?: boolean;
  children: React.ReactNode;
}

export interface RadioOptionProps
  extends Omit<
    React.InputHTMLAttributes<HTMLInputElement>,
    "checked" | "defaultChecked" | "name" | "onChange" | "size" | "type" | "value"
  > {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  radioSize?: RadioGroupSize;
  variant?: RadioGroupVariant;
  fullWidth?: boolean;
  containerClassName?: string;
  controlClassName?: string;
  labelClassName?: string;
  descriptionClassName?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
}

export interface RadioCardProps extends RadioOptionProps {
  eyebrow?: React.ReactNode;
}

type RadioGroupContextValue = {
  name: string;
  value?: string;
  setValue: (value: string, event: React.ChangeEvent<HTMLInputElement>) => void;
  radioSize: RadioGroupSize;
  variant: RadioGroupVariant;
  disabled?: boolean;
  error?: React.ReactNode;
};

const RadioGroupContext = React.createContext<RadioGroupContextValue | null>(
  null,
);

const controlSizes: Record<RadioGroupSize, string> = {
  sm: "size-4",
  md: "size-[18px]",
  lg: "size-5",
};

const dotSizes: Record<RadioGroupSize, string> = {
  sm: "size-1.5",
  md: "size-2",
  lg: "size-2.5",
};

const segmentSizes: Record<RadioGroupSize, string> = {
  sm: "min-h-8 px-3 text-[12px]",
  md: "min-h-9 px-3.5 text-[13px]",
  lg: "min-h-10 px-4 text-sm",
};

const labelSizes: Record<RadioGroupSize, string> = {
  sm: "text-[13px]",
  md: "text-sm",
  lg: "text-[15px]",
};

const rowGap: Record<RadioGroupSize, string> = {
  sm: "gap-2.5",
  md: "gap-3",
  lg: "gap-3.5",
};

const controlOffset: Record<RadioGroupSize, string> = {
  sm: "mt-px",
  md: "mt-0.5",
  lg: "mt-0.5",
};

const focusRing = cn(
  "peer-focus-visible:outline-none",
  "peer-focus-visible:ring-2 peer-focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)]",
  "peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-[var(--background)]",
);

const smooth =
  "transition-[background-color,border-color,box-shadow,color,opacity,transform] duration-250 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none";

function RadioMark({
  checked,
  variant,
  radioSize,
}: {
  checked: boolean;
  variant: RadioGroupVariant;
  radioSize: RadioGroupSize;
}) {
  if (variant === "command") {
    return (
      <span
        aria-hidden="true"
        className={cn(
          "grid rounded-full border",
          "border-[var(--border-strong)] bg-[var(--background)]",
          "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.35)]",
          focusRing,
          smooth,
          checked &&
            "border-[var(--foreground)] bg-[var(--foreground)] text-[var(--background)]",
          controlSizes[radioSize],
        )}
      >
        <svg
          aria-hidden="true"
          viewBox="0 0 16 16"
          fill="none"
          className={cn(
            "m-auto size-3 transform-gpu text-current opacity-0 scale-75",
            smooth,
            checked && "opacity-100 scale-100",
          )}
        >
          <path
            d="M3.4 8.2 6.45 11.25 12.6 4.75"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            style={{ strokeDasharray: 1, strokeDashoffset: checked ? 0 : 1 }}
            className="transition-[stroke-dashoffset] duration-300 ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none"
          />
        </svg>
      </span>
    );
  }

  return (
    <span
      aria-hidden="true"
      className={cn(
        "grid shrink-0 place-items-center rounded-full border",
        "border-[var(--border-strong)] bg-[var(--background)]",
        "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.32)]",
        focusRing,
        smooth,
        checked &&
          cn(
            "border-[var(--foreground)]",
            "shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
            "dark:shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_14%,transparent)]",
          ),
        controlSizes[radioSize],
      )}
    >
      <span
        className={cn(
          "rounded-full bg-[var(--foreground)] opacity-0 scale-[0.45]",
          "transform-gpu",
          smooth,
          checked && "opacity-100 scale-100",
          dotSizes[radioSize],
        )}
      />
    </span>
  );
}

function useRadioGroupContext(component: string) {
  const context = React.useContext(RadioGroupContext);
  if (!context) {
    throw new Error(`${component} must be used inside RadioGroup.`);
  }
  return context;
}

export function RadioGroup({
  value,
  defaultValue,
  onValueChange,
  name,
  label,
  description,
  error,
  radioSize = "md",
  variant = "orb",
  orientation = "vertical",
  disabled,
  children,
  className,
  ...props
}: RadioGroupProps) {
  const reactId = React.useId();
  const groupName = name ?? `radio-group-${reactId}`;
  const descriptionId = description ? `${groupName}-description` : undefined;
  const errorId = error ? `${groupName}-error` : undefined;
  const isControlled = value !== undefined;
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue);
  const selectedValue = isControlled ? value : uncontrolledValue;

  const setValue = React.useCallback(
    (nextValue: string, event: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) setUncontrolledValue(nextValue);
      onValueChange?.(nextValue, event);
    },
    [isControlled, onValueChange],
  );

  const context = React.useMemo<RadioGroupContextValue>(
    () => ({
      name: groupName,
      value: selectedValue,
      setValue,
      radioSize,
      variant,
      disabled,
      error,
    }),
    [disabled, error, groupName, radioSize, selectedValue, setValue, variant],
  );

  return (
    <RadioGroupContext.Provider value={context}>
      <fieldset
        aria-describedby={[descriptionId, errorId].filter(Boolean).join(" ") || undefined}
        aria-invalid={error ? true : undefined}
        disabled={disabled}
        className={cn("space-y-3.5", className)}
        {...props}
      >
        {label || description ? (
          <div className="space-y-1">
            {label ? (
              <legend className="text-sm font-semibold tracking-[-0.015em] text-[var(--foreground)]">
                {label}
              </legend>
            ) : null}
            {description ? (
              <p
                id={descriptionId}
                className="text-[12px] leading-[1.45] text-[var(--muted-foreground)]"
              >
                {description}
              </p>
            ) : null}
          </div>
        ) : null}
        <div
          data-slot="radio-group-list"
          data-orientation={orientation}
          className={cn(
            orientation === "horizontal"
              ? "flex flex-wrap items-stretch gap-2.5"
              : "space-y-2",
            variant === "segment" &&
              cn(
                "rounded-xl border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] p-1",
                "dark:bg-[color-mix(in_srgb,var(--foreground)_7%,var(--background))]",
                orientation === "horizontal" ? "inline-flex" : "space-y-1",
              ),
          )}
        >
          {children}
        </div>
        {error ? (
          <p
            id={errorId}
            className="text-[12px] leading-[1.45] font-medium text-red-600 dark:text-red-400"
          >
            {error}
          </p>
        ) : null}
      </fieldset>
    </RadioGroupContext.Provider>
  );
}

export const RadioOption = React.forwardRef<HTMLInputElement, RadioOptionProps>(
  (
    {
      value,
      label,
      description,
      leading,
      trailing,
      radioSize,
      variant,
      fullWidth = true,
      disabled,
      className,
      containerClassName,
      controlClassName,
      labelClassName,
      descriptionClassName,
      onChange,
      ...props
    },
    ref,
  ) => {
    const context = useRadioGroupContext("RadioOption");
    const optionSize = radioSize ?? context.radioSize;
    const optionVariant = variant ?? context.variant;
    const optionDisabled = disabled || context.disabled;
    const checked = context.value === value;
    const optionId = React.useId();
    const descriptionId = description ? `radio-option-${optionId}-description` : undefined;

    const handleChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.currentTarget.checked) context.setValue(value, event);
        onChange?.(event);
      },
      [context, onChange, value],
    );

    const input = (
      <input
        ref={ref}
        id={`radio-option-${optionId}`}
        type="radio"
        name={context.name}
        value={value}
        checked={checked}
        disabled={optionDisabled}
        aria-describedby={descriptionId}
        aria-invalid={context.error ? true : undefined}
        onChange={handleChange}
        className="peer sr-only"
        {...props}
      />
    );

    if (optionVariant === "segment") {
      return (
        <label
          data-slot="radio-option"
          data-state={checked ? "checked" : "unchecked"}
          data-disabled={optionDisabled ? "" : undefined}
          className={cn(
            "group/radio relative inline-flex cursor-pointer select-none items-center justify-center rounded-lg",
            "font-medium leading-none tracking-[-0.01em]",
            smooth,
            "text-[var(--muted-foreground)]",
            "hover:text-[var(--foreground)]",
            checked &&
              cn(
                "bg-[var(--surface)] text-[var(--foreground)]",
                "shadow-[0_1px_2px_rgba(0,0,0,0.07),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
                "dark:shadow-[0_1px_2px_rgba(0,0,0,0.36),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
              ),
            optionDisabled && "cursor-not-allowed opacity-45",
            fullWidth && "flex-1",
            segmentSizes[optionSize],
            containerClassName,
            className,
          )}
        >
          {input}
          <span className="truncate">{label}</span>
        </label>
      );
    }

    if (optionVariant === "command") {
      return (
        <label
          data-slot="radio-option"
          data-state={checked ? "checked" : "unchecked"}
          data-disabled={optionDisabled ? "" : undefined}
          className={cn(
            "group/radio relative flex cursor-pointer select-none items-start rounded-xl border p-3.5",
            "border-[var(--border)] bg-[var(--surface)]",
            "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.30)]",
            smooth,
            !optionDisabled &&
              "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)] hover:bg-[color-mix(in_srgb,var(--foreground)_1.8%,var(--surface))]",
            checked &&
              cn(
                "border-[color-mix(in_srgb,var(--foreground)_22%,transparent)] bg-[color-mix(in_srgb,var(--foreground)_2.5%,var(--surface))]",
                "shadow-[0_1px_2px_rgba(0,0,0,0.05),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
                "dark:shadow-[0_1px_3px_rgba(0,0,0,0.38),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
              ),
            optionDisabled && "cursor-not-allowed opacity-45",
            fullWidth ? "w-full" : "w-fit",
            rowGap[optionSize],
            containerClassName,
            className,
          )}
        >
          {input}
          {leading ? (
            <span className="mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--surface))] text-[var(--muted-foreground)] [&_svg]:size-4">
              {leading}
            </span>
          ) : null}
          <span className="min-w-0 flex-1">
            <span
              className={cn(
                "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
                labelSizes[optionSize],
                labelClassName,
              )}
            >
              {label}
            </span>
            {description ? (
              <span
                id={descriptionId}
                className={cn(
                  "mt-1 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                  descriptionClassName,
                )}
              >
                {description}
              </span>
            ) : null}
          </span>
          {trailing ? (
            <span className="shrink-0 pt-0.5 text-[12px] font-medium text-[var(--muted-foreground)]">
              {trailing}
            </span>
          ) : null}
          <RadioMark
            checked={checked}
            variant="command"
            radioSize={optionSize}
          />
        </label>
      );
    }

    return (
      <label
        data-slot="radio-option"
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={optionDisabled ? "" : undefined}
        className={cn(
          "group/radio relative flex cursor-pointer select-none items-start",
          rowGap[optionSize],
          fullWidth ? "w-full" : "w-fit",
          optionDisabled && "cursor-not-allowed opacity-45",
          containerClassName,
          className,
        )}
      >
        {input}
        <span className={cn(controlOffset[optionSize], controlClassName)}>
          <RadioMark checked={checked} variant="orb" radioSize={optionSize} />
        </span>
        <span className="min-w-0 flex-1 pt-px">
          <span
            className={cn(
              "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
              labelSizes[optionSize],
              labelClassName,
            )}
          >
            {label}
          </span>
          {description ? (
            <span
              id={descriptionId}
              className={cn(
                "mt-1 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                descriptionClassName,
              )}
            >
              {description}
            </span>
          ) : null}
        </span>
        {trailing ? (
          <span className="shrink-0 pt-0.5 text-[12px] font-medium text-[var(--muted-foreground)]">
            {trailing}
          </span>
        ) : null}
      </label>
    );
  },
);

RadioOption.displayName = "RadioOption";

export const RadioCard = React.forwardRef<HTMLInputElement, RadioCardProps>(
  (
    {
      eyebrow,
      leading,
      trailing,
      value,
      label,
      description,
      disabled,
      onChange,
      radioSize = "md",
      variant: _variant,
      fullWidth = true,
      containerClassName,
      controlClassName: _controlClassName,
      className,
      labelClassName,
      descriptionClassName,
      ...props
    },
    ref,
  ) => {
    const context = useRadioGroupContext("RadioCard");
    const checked = context.value === value;
    const optionDisabled = disabled || context.disabled;
    const optionId = React.useId();
    const descriptionId = description ? `radio-card-${optionId}-description` : undefined;

    const handleChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.currentTarget.checked) context.setValue(value, event);
        onChange?.(event);
      },
      [context, onChange, value],
    );

    return (
      <label
        data-slot="radio-card"
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={optionDisabled ? "" : undefined}
        className={cn(
          "group/radio-card relative block cursor-pointer select-none rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4",
          "shadow-[0_1px_2px_rgba(0,0,0,0.04)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.32)]",
          smooth,
          !optionDisabled &&
            "hover:border-[color-mix(in_srgb,var(--foreground)_18%,transparent)] hover:bg-[color-mix(in_srgb,var(--foreground)_1.8%,var(--surface))]",
          checked &&
            cn(
              "border-[color-mix(in_srgb,var(--foreground)_28%,transparent)]",
              "bg-[color-mix(in_srgb,var(--foreground)_2.8%,var(--surface))]",
              "shadow-[0_1px_2px_rgba(0,0,0,0.06),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
              "dark:shadow-[0_1px_3px_rgba(0,0,0,0.38),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
            ),
          optionDisabled && "cursor-not-allowed opacity-45",
          fullWidth ? "w-full" : "w-fit",
          containerClassName,
          className,
        )}
      >
        <input
          ref={ref}
          id={`radio-card-${optionId}`}
          type="radio"
          name={context.name}
          value={value}
          checked={checked}
          disabled={optionDisabled}
          aria-describedby={descriptionId}
          aria-invalid={context.error ? true : undefined}
          onChange={handleChange}
          className="peer sr-only"
          {...props}
        />
        <div
          className={cn(
            "pointer-events-none absolute right-3 top-3 grid size-5 place-items-center rounded-full",
            "border border-[var(--border-strong)] bg-[var(--background)] text-[var(--background)]",
            smooth,
            checked && "border-[var(--foreground)] bg-[var(--foreground)]",
          )}
        >
          <svg
            aria-hidden="true"
            viewBox="0 0 16 16"
            className={cn("size-3", smooth, checked ? "opacity-100" : "opacity-0")}
            fill="none"
          >
            <path
              d="M3.4 8.2 6.45 11.25 12.6 4.75"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>
        {eyebrow ? (
          <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.07em] text-[var(--muted-foreground)]">
            {eyebrow}
          </p>
        ) : null}
        {leading ? (
          <div className="mb-3 grid size-9 place-items-center rounded-xl border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3.5%,var(--surface))] text-[var(--foreground)] [&_svg]:size-[18px]">
            {leading}
          </div>
        ) : null}
        <span className="block min-w-0 pr-7">
          <span
            className={cn(
              "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
              labelSizes[radioSize],
              labelClassName,
            )}
          >
            {label}
          </span>
          {description ? (
            <span
              id={descriptionId}
              className={cn(
                "mt-1.5 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                descriptionClassName,
              )}
            >
              {description}
            </span>
          ) : null}
          {trailing ? (
            <span className="mt-3 inline-flex items-center rounded-md border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--surface))] px-2 py-0.5 text-[11px] font-medium tracking-[0.01em] text-[var(--muted-foreground)]">
              {trailing}
            </span>
          ) : null}
        </span>
      </label>
    );
  },
);

RadioCard.displayName = "RadioCard";
